}

._ab5x /*translucent fix*/{
    padding-top:0 
}
  
/* Dark Scrollbar*/
    scrollbar,
    scrollbar-corner,
    scrollbar,
    scrollbar-corner {
    background:#f5c9d3 !important;
    width:8px
  }
    scrollbar-button,
    scrollbar-button {
    display:none !important;
  }
    scrollbar-thumb,
    scrollbar-thumb {
    background:#f5c9d3 !important; 
    width:8px !important;
    border-radius:10px;
     transition:.1s !important;
  }
    scrollbar-thumb:not(:active):hover,
    scrollbar-thumb:not(:active):hover {
    background:#f5c9d3 !important;
     transition:.1s !important;
  }
    scrollbar-thumb:active,
    scrollbar-thumb:hover:active,
    scrollbar-thumb:active,
    scrollbar-thumb:hover:active {
    background:#f5c9d3 !important;
     transition:.1s !important;
  }
}
